-- Generated by rice-render for {{ meta.title }}: Paper Night's colourscheme,
-- "notebook". Linked to ~/.config/nvim/colors/rice.lua; rice@light.lua is the day.
--
-- A notebook under the lamp: cream type on the dark sheet, keywords in bold
-- gel-blue, numbers coral, strings green, comments in italic graphite. The
-- cursor line is the dim blue rule, the colour column and window separators
-- the margin line, and floats are black card in a kraft frame.
vim.cmd("highlight clear")
vim.g.colors_name = "rice"
vim.o.background = "dark"

local c = {
  paper    = "{{ colors.paper }}",
  card     = "{{ colors.card }}",
  desk     = "{{ colors.desk }}",
  crease   = "{{ colors.crease }}",
  carbon   = "{{ colors.carbon }}",
  pencil   = "{{ colors.pencil }}",
  graphite = "{{ colors.graphite }}",
  ink      = "{{ colors.ink }}",
  red      = "{{ ansi.color1 }}",
  green    = "{{ ansi.color2 }}",
  ochre    = "{{ ansi.color3 }}",
  plum     = "{{ ansi.color5 }}",
  teal     = "{{ ansi.color6 }}",
  sticky   = "{{ colors.sticky }}",
  pink     = "{{ colors.pink }}",
  mint     = "{{ colors.mint }}",
  kraft    = "{{ colors.kraft }}",
  rule     = "{{ colors.rule }}",          -- the cursor line
  ruled    = "{{ colors.rule }}",
  margin   = "{{ colors.margin }}",        -- the colour column and separators
  marginfg = "{{ colors.margin | lighten(0.12) }}",
  note     = "{{ colors.graphite }}",      -- comments
  lnr      = "{{ colors.paper | mix(colors.graphite, 0.32) }}",   -- line numbers, faint
}

local function hl(group, spec) vim.api.nvim_set_hl(0, group, spec) end

-- the page
hl("Normal",       { fg = c.carbon, bg = c.paper })
hl("NormalNC",     { fg = c.carbon, bg = c.paper })
hl("NormalFloat",  { fg = c.carbon, bg = c.card })
hl("FloatBorder",  { fg = c.kraft, bg = c.card })
hl("FloatTitle",   { fg = c.ink, bg = c.card, bold = true })
hl("Cursor",       { fg = c.paper, bg = c.carbon })
hl("CursorLine",   { bg = c.ruled })
hl("CursorColumn", { bg = c.ruled })
hl("CursorLineNr", { fg = c.red, bold = true })
hl("LineNr",       { fg = c.lnr })
hl("SignColumn",   { bg = c.paper })
hl("ColorColumn",  { bg = c.margin })
hl("Visual",       { fg = c.ink, bg = c.kraft })
hl("Search",       { fg = c.paper, bg = c.sticky })
hl("IncSearch",    { fg = c.paper, bg = c.pink })
hl("CurSearch",    { fg = c.paper, bg = c.pink })
hl("MatchParen",   { fg = c.red, bold = true, underline = true })
hl("Pmenu",        { fg = c.pencil, bg = c.card })
hl("PmenuSel",     { fg = c.ink, bg = c.kraft, bold = true })
hl("PmenuThumb",   { bg = c.crease })
hl("StatusLine",   { fg = c.ink, bg = c.card })
hl("StatusLineNC", { fg = c.graphite, bg = c.card })
hl("WinSeparator", { fg = c.marginfg })
hl("VertSplit",    { fg = c.marginfg })
hl("TabLine",      { fg = c.graphite, bg = c.card })
hl("TabLineSel",   { fg = c.ink, bg = c.kraft, bold = true })
hl("TabLineFill",  { bg = c.desk })
hl("Folded",       { fg = c.note, bg = c.card, italic = true })
hl("NonText",      { fg = c.crease })
hl("Whitespace",   { fg = c.crease })
hl("EndOfBuffer",  { fg = c.paper })
hl("Directory",    { fg = c.ink, bold = true })
hl("Title",        { fg = c.ink, bold = true })
hl("ErrorMsg",     { fg = c.red, bold = true })
hl("WarningMsg",   { fg = c.ochre })
hl("MoreMsg",      { fg = c.green })
hl("Question",     { fg = c.ink })
hl("SpellBad",     { sp = c.red, undercurl = true })
hl("SpellCap",     { sp = c.ink, undercurl = true })

-- the writing
hl("Comment",    { fg = c.note, italic = true })
hl("Constant",   { fg = c.red })
hl("Number",     { fg = c.red })
hl("Float",      { fg = c.red })
hl("Boolean",    { fg = c.red })
hl("Character",  { fg = c.green })
hl("String",     { fg = c.green })
hl("Identifier", { fg = c.carbon })
hl("Function",   { fg = c.carbon, bold = true })
hl("Statement",  { fg = c.ink, bold = true })
hl("Keyword",    { fg = c.ink, bold = true })
hl("Conditional", { fg = c.ink, bold = true })
hl("Repeat",     { fg = c.ink, bold = true })
hl("Operator",   { fg = c.pencil })
hl("PreProc",    { fg = c.plum })
hl("Include",    { fg = c.ink, bold = true })
hl("Type",       { fg = c.teal })
hl("Special",    { fg = c.plum })
hl("Delimiter",  { fg = c.pencil })
hl("Todo",       { fg = c.paper, bg = c.sticky, bold = true })
hl("Error",      { fg = c.red, underline = true })
hl("Underlined", { fg = c.ink, underline = true })

-- treesitter
for from, to in pairs({
  ["@comment"] = "Comment", ["@string"] = "String", ["@string.escape"] = "Special",
  ["@number"] = "Number", ["@number.float"] = "Float", ["@boolean"] = "Boolean",
  ["@constant"] = "Constant", ["@constant.builtin"] = "Constant",
  ["@function"] = "Function", ["@function.call"] = "Function", ["@method"] = "Function",
  ["@keyword"] = "Keyword", ["@keyword.function"] = "Keyword", ["@keyword.return"] = "Keyword",
  ["@conditional"] = "Conditional", ["@repeat"] = "Repeat", ["@type"] = "Type",
  ["@type.builtin"] = "Type", ["@variable"] = "Identifier", ["@property"] = "Identifier",
  ["@operator"] = "Operator", ["@punctuation"] = "Delimiter", ["@tag"] = "Keyword",
  ["@tag.attribute"] = "Type", ["@markup.heading"] = "Title", ["@markup.link"] = "Underlined",
}) do hl(from, { link = to }) end
hl("@variable.parameter", { fg = c.carbon, italic = true })
hl("@variable.builtin",   { fg = c.plum })

-- diagnostics: red for errors, ochre for warnings, ink for information, graphite hints
hl("DiagnosticError", { fg = c.red })
hl("DiagnosticWarn",  { fg = c.ochre })
hl("DiagnosticInfo",  { fg = c.ink })
hl("DiagnosticHint",  { fg = c.note })
hl("DiagnosticOk",    { fg = c.green })
hl("DiagnosticUnderlineError", { sp = c.red, undercurl = true })
hl("DiagnosticUnderlineWarn",  { sp = c.ochre, undercurl = true })
hl("DiagnosticUnderlineInfo",  { sp = c.ink, undercurl = true })
hl("DiagnosticUnderlineHint",  { sp = c.graphite, undercurl = true })
hl("DiagnosticVirtualTextError", { fg = c.red, italic = true })
hl("DiagnosticVirtualTextWarn",  { fg = c.ochre, italic = true })
hl("DiagnosticVirtualTextInfo",  { fg = c.ink, italic = true })
hl("DiagnosticVirtualTextHint",  { fg = c.note, italic = true })

-- diffs and git, a faint coloured wash on the dark sheet
hl("DiffAdd",    { bg = "{{ colors.paper | mix(colors.mint, 0.18) }}" })
hl("DiffChange", { bg = "{{ colors.paper | mix(colors.sticky, 0.14) }}" })
hl("DiffDelete", { fg = c.red, bg = "{{ colors.paper | mix(colors.pink, 0.16) }}" })
hl("DiffText",   { bg = "{{ colors.paper | mix(colors.sticky, 0.3) }}" })
hl("GitSignsAdd",    { fg = c.green })
hl("GitSignsChange", { fg = c.ink })
hl("GitSignsDelete", { fg = c.red })

-- terminal
for i, col in ipairs({
  "{{ ansi.color0 }}", "{{ ansi.color1 }}", "{{ ansi.color2 }}", "{{ ansi.color3 }}",
  "{{ ansi.color4 }}", "{{ ansi.color5 }}", "{{ ansi.color6 }}", "{{ ansi.color7 }}",
  "{{ ansi.color8 }}", "{{ ansi.color9 }}", "{{ ansi.color10 }}", "{{ ansi.color11 }}",
  "{{ ansi.color12 }}", "{{ ansi.color13 }}", "{{ ansi.color14 }}", "{{ ansi.color15 }}",
}) do vim.g["terminal_color_" .. (i - 1)] = col end

-- floats: black card in a kraft frame (the other rices' RiceBorder() still works)
for i = 1, 4 do hl("RiceBorder" .. i, { fg = c.kraft, bg = c.card }) end
function _G.RiceBorder()
  return { "┌", "─", "┐", "│", "┘", "─", "└", "│" }
end

-- follow `rice mode` (nvim/mode.lua, started once per nvim)
pcall(function() require("rice.mode").watch() end)
